package com.ramka.domain.usecaseimport com.ramka.domain.util.OfflineSignalTrackerimport kotlinx.coroutines.CancellationException/** * Лёгкий текстовый сигнал собеседнику, когда файл не ушёл из-за недоступности соединения. * * Текст отправляется ОБЫЧНЫМ путём текстовых сообщений ([sendText] = SendMessageUseCase: * saveOutgoing + Outbox + попытка доставки), а не файловым транспортом, — поэтому, если * собеседник офлайн, сообщение останется в очереди и дойдёт, когда он появится (в т.ч. через релей). * Частоту ограничивает [OfflineSignalTracker]. */class OfflineFileSignal(    private val tracker: OfflineSignalTracker,    private val sendText: suspend (contactId: String, text: String) -> Unit) {    /** @return true, если сигнал поставлен на отправку; false — подавлен защитой от спама или сбой. */    suspend operator fun invoke(contactId: String, fileMessageId: String): Boolean {        if (!tracker.tryAcquire(contactId, fileMessageId)) return false        return try {            sendText(contactId, TEXT)            tracker.markNotified(fileMessageId)            true        } catch (e: CancellationException) {            tracker.rollback(contactId)            throw e        } catch (e: Exception) {            tracker.rollback(contactId)            false        }    }    companion object {        const val TEXT = "Вам пытаются отправить файл. Откройте приложение, чтобы получить его."    }}